#include <cstdio>
#include <algorithm>
#include <vector>
#include <queue>

using namespace std;

const int N = 1e5 + 5;
const long long oo = 1e18;

int n, m;
int a, b;
int c[N];
vector<pair<int, int>> e[N];
long long dis[N];
priority_queue<pair<long long, int>> q;
long long ans;

int main() {
    scanf("%d%d", &n, &m);
    scanf("%d%d", &a, &b);
    for (int i = 1; i <= n; i++)
        scanf("%d", &c[i]);
    for (int i = 1; i <= m; i++) {
        int u, v, w;
        scanf("%d%d%d", &u, &v, &w);
        e[u].emplace_back(make_pair(v, w));
        e[v].emplace_back(make_pair(u, w));
    }
    for (int i = 1; i <= n; i++)
        dis[i] = oo;
    dis[b] = 0;
    q.push(make_pair(-dis[b], b));
    while (!q.empty()) {
        auto p = q.top();
        q.pop();
        if (dis[p.second] != -p.first)
            continue;
        int u = p.second;
        for (auto r : e[u]) {
            int v = r.first, w = r.second;
            if (dis[v] > dis[u] + w) {
                dis[v] = dis[u] + w;
                q.push(make_pair(-dis[v], v));
            }
        }
    }
    for (int i = 1; i <= n; i++)
        if (dis[i] < dis[a])
            ans += c[i];
    printf("%lld\n", ans);
    return 0;
}

#include <cstdio>
#include <algorithm>

using namespace std;

const int L = 20;
const int N = 2e5 + 5;
const int oo = 1e9;

int n, m;
int t[N], jump[L][N];
int cnt[N], tot;
int ans;

int go(int u) {
    int cnt = 0, ans = 0;
    for (int i = L - 1; i >= 0; i--)
        if (cnt + jump[i][u] <= n) {
            cnt += jump[i][u];
            ans += 1 << i;
            u = (u + jump[i][u] - 1) % n + 1;
        }
    return ans;
}

int main() {
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &t[i]);
        t[i + n] = t[i];
    }
    for (int i = 1, r = 0; i <= n; i++) {
        while (tot < m) {
            r++;
            if (!cnt[t[r]]++)
                tot++;
        }
        jump[0][i] = r - i + 1;
        if (!--cnt[t[i]])
            tot--;
    }
    for (int i = 1; i < L; i++)
        for (int j = 1; j <= n; j++) {
            int tar = (j + jump[i - 1][j] - 1) % n + 1;
            jump[i][j] = min(jump[i - 1][j] + jump[i - 1][tar], oo);
        }
    for (int i = 1; i <= n; i++)
        ans = max(ans, go(i));
    printf("%d\n", ans);
    return 0;
}
